import { Tabs, type TabsChangeDetail } from '@absoluteui/components/tabs';

const host = document.createElement('div');
document.body.append(host);
const tabs = Tabs.create(host, {
  label: 'Reports',
  activation: 'manual',
  tabs: [
    { id: 'daily', label: 'Daily' },
    { id: 'weekly', label: 'Weekly' },
  ],
});
const fill = (id: string): void => {
  const panel = tabs.panel(id);
  if (panel && panel.childElementCount === 0) {
    const table = document.createElement('table');
    panel.append(table);
  }
};
fill(tabs.value);
host.addEventListener('aui-change', (event) => {
  fill((event as CustomEvent<TabsChangeDetail>).detail.value);
});

